<?php define('APP_ROOT','..');require __DIR__.'/../includes/auth.php';require_role('user');require __DIR__.'/../config/database.php';require __DIR__.'/../includes/functions.php';$id=(int)$_SESSION['id_user'];if(isset($_GET['batal'])){$pid=(int)$_GET['batal'];$stmt=mysqli_prepare($koneksi,"DELETE FROM peminjaman WHERE id_peminjaman=? AND id_user=? AND status='pending'");mysqli_stmt_bind_param($stmt,'ii',$pid,$id);mysqli_stmt_execute($stmt);set_flash(mysqli_stmt_affected_rows($stmt)?'success':'danger',mysqli_stmt_affected_rows($stmt)?'Pengajuan dibatalkan.':'Pengajuan tidak dapat dibatalkan.');header('Location: riwayat.php');exit;}$stmt=mysqli_prepare($koneksi,'SELECT p.*,b.kode_buku,b.judul FROM peminjaman p JOIN buku b ON b.id_buku=p.id_buku WHERE p.id_user=? ORDER BY p.created_at DESC');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$rows=mysqli_stmt_get_result($stmt);$page_title='Riwayat Peminjaman';require __DIR__.'/../includes/header.php';?><section class="panel table-wrap"><table><thead><tr><th>Buku</th><th>Pengajuan</th><th>Pinjam / Tempo</th><th>Kembali</th><th>Status</th><th>Denda</th><th></th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($rows)):$badge=status_badge($r['status']);?><tr><td><b><?=e($r['judul'])?></b><small><?=e($r['kode_buku'])?></small></td><td><?=format_tanggal_id($r['tanggal_pengajuan'])?></td><td><?=format_tanggal_id($r['tanggal_pinjam'])?><small><?=format_tanggal_id($r['tanggal_jatuh_tempo'])?></small></td><td><?=format_tanggal_id($r['tanggal_kembali'])?></td><td><span class="badge <?=$badge[1]?>"><?=$badge[0]?></span></td><td><?=$r['hari_terlambat']?> hari<small><?=format_rupiah((int)$r['denda'])?></small></td><td><?php if($r['status']==='pending'):?><a class="danger-link" data-confirm="Batalkan pengajuan ini?" href="?batal=<?=$r['id_peminjaman']?>">Batalkan</a><?php endif;?></td></tr><?php endwhile;?></tbody></table></section><?php require __DIR__.'/../includes/footer.php';
